# --- Helper functions for extracting prompts by genre ---

def get_prompts(genre):
    """Get all prompts for a single genre."""
    return [ps[genre] for ps in PROMPT_SETS]


def get_prompt_pairs(genre_a, genre_b):
    """Get matched prompt pairs for two genres."""
    return [(ps[genre_a], ps[genre_b]) for ps in PROMPT_SETS]
